(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-993":{scenario:{company:"Trung tâm An ninh Hàng không Tân Hải",supervisor:{name:"Đinh Công Lâm",role:{vi:"Trưởng ca Soi chiếu An ninh",en:"Screening Shift Supervisor"}},ref_code:"SCR-3306",title:{vi:"Đúng quy định chất lỏng. Đúng điện năng pin. Mọi cảnh báo phải được giải quyết.",en:"Right liquids rule. Right battery rating. Every alarm resolved."},brief:{vi:"Tại điểm soi chiếu chuyến bay quốc tế, hành lý xách tay của một khách có chai mỹ phẩm dung tích 150 ml chỉ còn khoảng 60 ml và một sạc dự phòng ghi 27500 mAh, 3,6 V, không ghi Wh. Bản nháp phiếu xử lý SCR-3306 ghi chai mỹ phẩm ACCEPT và điện năng sạc 137.5 Wh (cần hãng chấp thuận). Đối chiếu quy trình soi chiếu đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"At an international departures checkpoint, a passenger's cabin bag holds a 150 ml cosmetic bottle with only about 60 ml left and a power bank labelled 27500 mAh, 3.6 V, with no Wh rating. Draft screening record SCR-3306 marks the bottle ACCEPT and the power bank at 137.5 Wh (airline approval needed). Compare it with the approved screening procedure, correct both fields and write an evidence-based report."},reference_title:{vi:"Quy trình soi chiếu & kiểm soát vật phẩm đã duyệt · SCR-3306",en:"Approved screening & prohibited items procedure · SCR-3306"},fields:[{id:"LAG_DECISION",label:{vi:"Quyết định với chai mỹ phẩm 150 ml",en:"Decision on the 150 ml cosmetic bottle"},initial:"ACCEPT",expected:"REJECT",choices:["ACCEPT","REJECT","EXEMPT"],reference:"Quy trình kiểm soát chất lỏng (LAGs)",hint:{vi:"Giới hạn 100 ml xét theo dung tích ghi trên vật chứa, không theo lượng còn bên trong; mỹ phẩm không thuộc diện miễn trừ.",en:"The 100 ml limit applies to the container capacity, not the amount left inside; cosmetics are not exempt."}},{id:"PB_WH",label:{vi:"Điện năng sạc dự phòng (Wh)",en:"Power bank energy rating (Wh)"},initial:"137.5",expected:"99",reference:"Phiếu kiểm tra pin lithium",ref_value:{vi:"Nhãn: 27500 mAh, điện áp danh định 3,6 V, không ghi Wh",en:"Label: 27500 mAh, nominal voltage 3.6 V, no Wh shown"},hint:{vi:"Bản nháp nhân với điện áp cổng USB 5 V; quy định dùng điện áp danh định của cell pin.",en:"The draft multiplied by the 5 V USB output; the rule uses the cell's nominal voltage."}}],sop32:{vi:"Điện năng (Wh) = dung lượng (mAh) x điện áp danh định (V) ÷ 1000. Pin dự phòng đến 100 Wh: mang xách tay; trên 100 đến 160 Wh: cần hãng chấp thuận; trên 160 Wh: cấm; không để trong hành lý ký gửi.",en:"Energy (Wh) = capacity (mAh) x nominal voltage (V) ÷ 1000. Spare batteries up to 100 Wh: cabin bag; over 100 to 160 Wh: airline approval needed; over 160 Wh: forbidden; never in checked baggage."},context:{label:"SCREENING / SCR-3306",metrics:[{label:{vi:"Dung tích chai",en:"Bottle capacity"},value:"150 ml"},{label:{vi:"Nhãn sạc dự phòng",en:"Power bank label"},value:"27500 mAh / 3.6 V"},{label:{vi:"Giới hạn chất lỏng",en:"Liquids limit"},value:"100 ml / 1 L bag"}]},crisis:{vi:"Máy phát hiện vết chất nổ (ETD) báo động trên quai túi của một khách khác. Trưởng nhóm nói: “Chắc do kem dưỡng tay thôi, hàng đang dài, khách lại là người quen của sếp, em cho qua luôn đi.”",en:"The explosive trace detector (ETD) alarms on another passenger's bag handle. The team lead says: “It's probably hand cream, the queue is long and he knows the boss, just clear him.”"},options:{safe:{vi:"Không cho qua khi cảnh báo chưa được giải quyết; lấy mẫu lại, lục soát trực quan theo quy trình, báo trưởng ca và đề nghị mở thêm làn để giảm ùn tắc.",en:"Do not clear an unresolved alarm; re-sample and hand search per procedure, inform the shift supervisor and request an extra lane to ease the queue."},shortcut:{vi:"Cho khách qua vì là người quen của lãnh đạo và hàng đang dài.",en:"Clear the passenger because he knows management and the queue is long."},wait:{vi:"Để túi sang một bên chưa xử lý và tiếp tục soi khách khác.",en:"Put the bag aside unresolved and keep screening other passengers."}},questions:{vi:["Vì sao chai 150 ml chỉ còn 60 ml vẫn phải REJECT? Quy định nào chứng minh và khách có những lựa chọn hợp lệ nào?","Trình bày cách tính điện năng sạc dự phòng và vì sao mọi cảnh báo ETD phải được giải quyết trước khi cho qua."],en:["Why must a 150 ml bottle with only 60 ml left still be REJECT? Which rule proves it and what valid options does the passenger have?","Explain how you calculated the power bank rating and why every ETD alarm must be resolved before clearance."]},hints:{vi:["Đọc dung tích in trên vật chứa và so với giới hạn trong quy trình kiểm soát chất lỏng.","Lấy dung lượng mAh và điện áp danh định trên nhãn rồi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không có ngoại lệ vì quan hệ cá nhân, cảnh báo chưa giải quyết thì không được cho qua."],en:["Read the capacity printed on the container and compare it with the liquids procedure limit.","Take the mAh capacity and nominal voltage from the label and apply the formula in SOP 3.2.","Re-read SOP 4.2: there are no exceptions for personal connections and an unresolved alarm is never cleared."]}},learning:{summary:{vi:"Chuyên viên soi chiếu an ninh hàng không kiểm tra hành khách, hành lý xách tay, hành lý ký gửi, hàng hóa và người, phương tiện vào khu vực hạn chế bằng máy soi tia X, cổng từ, thiết bị phát hiện vết chất nổ và lục soát trực quan, nhằm ngăn vật phẩm nguy hiểm lên tàu bay. Nghề đòi hỏi kỹ năng đọc ảnh soi, nắm chắc danh mục vật phẩm cấm và hạn chế, giao tiếp lịch sự nhưng kiên quyết và tuyệt đối không ngoại lệ.",en:"An aviation security screening officer screens passengers, cabin and hold baggage, cargo and people and vehicles entering restricted areas using X-ray, walk-through metal detectors, explosive trace detection and hand searches to keep dangerous items off aircraft. The role requires image interpretation skills, solid knowledge of prohibited and restricted items, courteous but firm communication and zero exceptions."},responsibilities:{vi:["Soi chiếu hành lý bằng máy tia X, đọc và phân tích ảnh để phát hiện vật phẩm nguy hiểm.","Kiểm tra hành khách qua cổng từ, máy soi toàn thân và lục soát trực quan khi có cảnh báo.","Áp dụng quy định chất lỏng (LAGs), pin lithium và hàng nguy hiểm trong hành lý.","Giải quyết mọi cảnh báo bằng thiết bị ETD, lục soát và báo cáo vật phẩm khả nghi.","Ghi sổ, lập biên bản tạm giữ vật phẩm và phối hợp lực lượng chức năng khi có tình huống."],en:["Screen baggage by X-ray and interpret images to detect dangerous items.","Screen passengers through metal detectors and body scanners and hand search on alarm.","Apply the liquids (LAGs), lithium battery and dangerous goods rules for baggage.","Resolve every alarm with ETD and searches and report suspicious items.","Keep logs, record surrendered items and coordinate with authorities when incidents arise."]},competencies:[{name:{vi:"Đọc ảnh soi tia X",en:"X-ray image interpretation"},desc:{vi:"Nhận diện vũ khí, chất nổ, linh kiện khả nghi qua hình dạng, màu vật liệu và mật độ.",en:"Recognise weapons, explosives and suspicious parts by shape, material colour and density."}},{name:{vi:"Lục soát trực quan",en:"Hand search"},desc:{vi:"Lục soát người và hành lý có hệ thống, tôn trọng hành khách và có người chứng kiến khi cần.",en:"Search people and bags systematically, respectfully and with a witness when required."}},{name:{vi:"Quy định vật phẩm nguy hiểm",en:"Dangerous items rules"},desc:{vi:"Áp đúng giới hạn chất lỏng, pin lithium, vật sắc nhọn và các trường hợp miễn trừ.",en:"Apply liquid, lithium battery and sharp item limits and the permitted exemptions."}},{name:{vi:"Giao tiếp với hành khách",en:"Passenger communication"},desc:{vi:"Giải thích quy định ngắn gọn, đưa ra lựa chọn hợp lệ và hạ nhiệt khi khách bức xúc.",en:"Explain rules briefly, offer valid options and calm upset passengers."}},{name:{vi:"Liêm chính & cảnh giác",en:"Integrity & vigilance"},desc:{vi:"Không ngoại lệ vì quen biết hay ùn tắc, giữ tập trung và báo cáo mọi áp lực bất thường.",en:"Make no exceptions for connections or queues, stay alert and report any undue pressure."}}],knowledge:{vi:["Phụ lục 17 Công ước Chicago (ICAO Annex 17) về an ninh hàng không.","Luật Hàng không dân dụng Việt Nam 2006 (sửa đổi, bổ sung 2014) và quy định về an ninh hàng không.","Quy định hạn chế chất lỏng, aerosol, gel (LAGs): vật chứa tối đa 100 ml trong túi nhựa trong suốt tối đa 1 lít.","Hướng dẫn kỹ thuật ICAO (Doc 9284) và quy định hàng nguy hiểm của IATA về pin lithium mang theo người.","Danh mục vật phẩm nguy hiểm cấm và hạn chế mang lên tàu bay do nhà chức trách hàng không công bố."],en:["ICAO Annex 17 on aviation security.","Vietnam Civil Aviation Law 2006 (amended 2014) and aviation security regulations.","Liquids, aerosols and gels (LAGs) rules: containers up to 100 ml in a clear bag of up to 1 litre.","ICAO Technical Instructions (Doc 9284) and IATA dangerous goods rules on passenger lithium batteries.","The list of prohibited and restricted items published by the aviation authority."]},tools:["Máy soi tia X đa góc","Cổng từ & máy dò kim loại cầm tay","Thiết bị phát hiện vết chất nổ (ETD)","Máy soi toàn thân","Hệ thống chiếu ảnh nguy hiểm giả lập (TIP)"],kpis:{vi:["Tỷ lệ phát hiện ảnh nguy hiểm giả lập (TIP) của từng nhân viên.","Tỷ lệ cảnh báo được giải quyết đúng quy trình (mục tiêu 100%).","Thời gian chờ soi chiếu bình quân của hành khách giờ cao điểm.","Số lần để lọt vật phẩm trong thử nghiệm an ninh bí mật (mục tiêu bằng 0)."],en:["Threat image projection (TIP) detection rate per officer.","Share of alarms resolved per procedure (target 100%).","Average passenger waiting time at peak hours.","Items missed in covert security tests (target zero)."]},day:[{time:"04:30",vi:"Nhận ca, kiểm tra thiết bị, thử máy soi và ETD theo danh mục đầu ca.",en:"Start the shift and test X-ray and ETD equipment against the opening checklist."},{time:"05:00",vi:"Soi chiếu cao điểm sáng, luân phiên vị trí đọc ảnh tối đa 20 phút mỗi lượt.",en:"Screen the morning peak, rotating off image reading every 20 minutes at most."},{time:"09:00",vi:"Giải quyết cảnh báo, lục soát túi và lập biên bản tạm giữ vật phẩm.",en:"Resolve alarms, search bags and record surrendered items."},{time:"11:00",vi:"Huấn luyện nhận dạng ảnh và xem kết quả TIP của ca.",en:"Do image recognition training and review the shift's TIP results."},{time:"12:30",vi:"Ghi sổ, bàn giao vật phẩm tạm giữ và báo cáo trưởng ca.",en:"Update the log, hand over surrendered items and report to the supervisor."}],mistakes:{vi:["Xét giới hạn 100 ml theo lượng chất lỏng còn lại thay vì dung tích vật chứa.","Tính điện năng pin bằng điện áp đầu ra 5 V thay vì điện áp danh định của cell.","Cho qua khi cảnh báo chưa được giải quyết vì ùn tắc hoặc vì quan hệ cá nhân."],en:["Judging the 100 ml limit by the amount left rather than the container capacity.","Calculating battery energy with the 5 V output instead of the cell's nominal voltage.","Clearing an unresolved alarm because of queues or personal connections."]},career:[{vi:"Nhân viên soi chiếu tập sự",en:"Trainee screening officer"},{vi:"Nhân viên soi chiếu an ninh hàng không",en:"Aviation security screening officer"},{vi:"Trưởng nhóm, trưởng ca soi chiếu",en:"Screening team lead, shift supervisor"},{vi:"Giám sát chất lượng an ninh hàng không",en:"Aviation security quality inspector"}],glossary:[{term:"LAGs",vi:"Chất lỏng, aerosol và gel bị giới hạn khi mang lên khoang khách chuyến bay quốc tế.",en:"Liquids, aerosols and gels restricted in cabin baggage on international flights."},{term:"ETD",vi:"Thiết bị phát hiện vết chất nổ bằng cách lấy mẫu bề mặt và phân tích.",en:"Explosive trace detection equipment that samples and analyses surfaces."},{term:"TIP",vi:"Hệ thống chèn ảnh vật nguy hiểm giả lập vào ảnh soi để đo và duy trì kỹ năng nhân viên.",en:"System that inserts fictional threat images into scans to measure and maintain skills."},{term:"Wh",vi:"Oát giờ, đơn vị điện năng của pin, bằng dung lượng (Ah) nhân điện áp danh định (V).",en:"Watt-hour, a battery energy unit equal to capacity (Ah) times nominal voltage (V)."},{term:"Alarm resolution",vi:"Quy trình xác định nguyên nhân cảnh báo và loại trừ mối đe dọa trước khi cho qua.",en:"The process of identifying an alarm's cause and ruling out a threat before clearance."}],quiz:[{q:{vi:"Sạc dự phòng 20000 mAh, điện áp danh định 3,7 V. Điện năng là bao nhiêu?",en:"A 20000 mAh power bank with a nominal voltage of 3.7 V. What is its energy rating?"},options:{vi:["100 Wh","74 Wh","20 Wh","370 Wh"],en:["100 Wh","74 Wh","20 Wh","370 Wh"]},answer:1,explain:{vi:"Điện năng = 20000 x 3,7 ÷ 1000 = 74 Wh, được mang xách tay.",en:"Energy = 20000 x 3.7 ÷ 1000 = 74 Wh, allowed in the cabin bag."}},{q:{vi:"Chai 200 ml chỉ còn 30 ml nước hoa trong hành lý xách tay chuyến quốc tế được xử lý thế nào?",en:"A 200 ml bottle with only 30 ml of perfume in a cabin bag on an international flight is handled how?"},options:{vi:["Cho qua vì còn ít","Cho qua nếu khách hứa không dùng","Không cho mang lên khoang khách","Đổ bớt ra rồi cho qua"],en:["Allow it since little is left","Allow it if the passenger promises not to use it","Not allowed in the cabin","Pour some out and allow it"]},answer:2,explain:{vi:"Giới hạn xét theo dung tích vật chứa; khách có thể gửi hành lý ký gửi hoặc bỏ lại.",en:"The limit is by container capacity; the passenger may check it in or surrender it."}},{q:{vi:"Máy ETD báo động, trưởng nhóm bảo cho qua vì khách quen lãnh đạo. Bạn làm gì?",en:"The ETD alarms and the team lead says to clear the passenger who knows management. What do you do?"},options:{vi:["Cho qua theo chỉ đạo","Cho qua nhưng ghi chú vào sổ","Hỏi khách có mang chất nổ không rồi cho qua","Giải quyết cảnh báo theo quy trình và báo trưởng ca"],en:["Clear him as instructed","Clear him but note it in the log","Ask if he carries explosives and clear him","Resolve the alarm per procedure and inform the shift supervisor"]},answer:3,explain:{vi:"Mọi cảnh báo phải được giải quyết trước khi cho qua; quan hệ cá nhân không phải lý do ngoại lệ.",en:"Every alarm must be resolved before clearance; personal connections are never grounds for exception."}},{q:{vi:"Sạc dự phòng 140 Wh của hành khách được xử lý ra sao?",en:"How is a passenger's 140 Wh power bank handled?"},options:{vi:["Mang xách tay khi có chấp thuận của hãng, tối đa 2 chiếc","Để trong hành lý ký gửi","Cấm hoàn toàn","Mang tự do không giới hạn"],en:["Cabin bag with airline approval, maximum 2 units","Packed in checked baggage","Completely forbidden","Carried freely without limits"]},answer:0,explain:{vi:"Pin dự phòng trên 100 đến 160 Wh chỉ mang xách tay khi được hãng chấp thuận, tối đa 2 chiếc mỗi khách.",en:"Spare batteries over 100 to 160 Wh go only in cabin bags with airline approval, at most 2 per passenger."}}],tools_en:["Multi-view X-ray screening machine","Walk-through & handheld metal detectors","Explosive trace detector (ETD)","Full-body scanner","Threat image projection system (TIP)"]}}})})(window.KKR);
